var breakpoints = (function () {
    "use strict";

    function e(config) {
        t.init(config);
    }

    var t = {
        list: null,
        media: {},
        events: [],
        init: function (config) {
            t.list = config;
            window.addEventListener("resize", t.poll);
            window.addEventListener("orientationchange", t.poll);
            window.addEventListener("load", t.poll);
            window.addEventListener("fullscreenchange", t.poll);
        },
        active: function (query) {
            var type, name, mediaQuery, min, max, unit;
            if (!(query in t.media)) {
                if (query.startsWith(">=")) {
                    type = "gte";
                    name = query.substr(2);
                } else if (query.startsWith("<=")) {
                    type = "lte";
                    name = query.substr(2);
                } else if (query.startsWith(">")) {
                    type = "gt";
                    name = query.substr(1);
                } else if (query.startsWith("<")) {
                    type = "lt";
                    name = query.substr(1);
                } else if (query.startsWith("!")) {
                    type = "not";
                    name = query.substr(1);
                } else {
                    type = "eq";
                    name = query;
                }

                if (name && name in t.list) {
                    var sizes = t.list[name];
                    if (Array.isArray(sizes)) {
                        min = parseInt(sizes[0], 10);
                        max = parseInt(sizes[1], 10);
                        unit = sizes[0].replace(min, "") || "px";

                        if (isNaN(min)) {
                            if (isNaN(max)) return;
                            unit = sizes[1].replace(max, "");
                        } else {
                            unit = sizes[0].replace(min, "");
                        }

                        switch (type) {
                            case "gte":
                                mediaQuery = isNaN(min) ? "screen" : `screen and (min-width: ${min}${unit})`;
                                break;
                            case "lte":
                                mediaQuery = isNaN(max) ? "screen" : `screen and (max-width: ${max}${unit})`;
                                break;
                            case "gt":
                                mediaQuery = isNaN(max) ? "screen and (min-width: -1px)" : `screen and (min-width: ${max + 1}${unit})`;
                                break;
                            case "lt":
                                mediaQuery = isNaN(min) ? "screen and (max-width: -1px)" : `screen and (max-width: ${min - 1}${unit})`;
                                break;
                            case "not":
                                mediaQuery = `screen and (max-width: ${min - 1}${unit}), screen and (min-width: ${max + 1}${unit})`;
                                break;
                            default:
                                mediaQuery = `screen and (min-width: ${min}${unit}) and (max-width: ${max}${unit})`;
                        }
                    } else {
                        mediaQuery = sizes.startsWith("(") ? `screen and ${sizes}` : sizes;
                    }
                    t.media[query] = mediaQuery;
                }
            }

            return t.media[query] && window.matchMedia(t.media[query]).matches;
        },
        on: function (query, handler) {
            t.events.push({ query, handler, state: false });
            if (t.active(query)) handler();
        },
        poll: function () {
            t.events.forEach(function (event) {
                if (t.active(event.query)) {
                    if (!event.state) {
                        event.state = true;
                        event.handler();
                    }
                } else {
                    event.state = false;
                }
            });
        },
    };

    e._ = t;
    e.on = function (query, handler) {
        t.on(query, handler);
    };
    e.active = function (query) {
        return t.active(query);
    };

    return e;
})();

// Exportálás különböző környezetekhez
if (typeof define === "function" && define.amd) {
    define([], function () {
        return breakpoints;
    });
} else if (typeof module !== "undefined" && module.exports) {
    module.exports = breakpoints;
} else {
    window.breakpoints = breakpoints;
}
